/**
 * @file 브라우저에서 직접 열 수 있는 단일 HTML을 생성합니다.
 * 개발 원본은 그대로 두고 JavaScript 모듈과 CSS를 play.html 안에 포함합니다.
 * 빌드 때만 Node.js·npm·네트워크가 필요하며, 생성된 파일은 서버 없이 실행됩니다.
 */

import { ACT_ART } from "./data/art.mjs";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const directory = fileURLToPath(new URL(".", import.meta.url));
const outputPath = join(directory, "play.html");
const generatedMarker =
  "<!-- Generated by build-standalone.mjs; edit the source modules instead. -->";

// 처음 만든 사용자 파일을 같은 이름으로 덮어쓰지 않도록 생성 표시를 확인합니다.
if (
  existsSync(outputPath) &&
  !readFileSync(outputPath, "utf8").startsWith(generatedMarker)
) {
  throw new Error(
    "기존 play.html은 이 도구가 만든 파일이 아닙니다. 파일을 보존한 뒤 다시 실행하세요.",
  );
}

// 버전을 고정한 컴파일러가 import를 하나의 즉시 실행 함수로 묶습니다.
// npm의 기본 무결성·TLS 검증을 그대로 사용하며 캐시는 임시 디렉터리에 둡니다.
const javascript = execFileSync(
  "npm",
  [
    "exec",
    "--yes",
    "--cache",
    join(tmpdir(), "ashen-standalone-npm-cache"),
    "--package=esbuild@0.25.5",
    "--",
    "esbuild",
    "app.mjs",
    "--bundle",
    "--format=iife",
    "--target=es2022",
    "--charset=utf8",
    "--legal-comments=none",
  ],
  { cwd: directory, encoding: "utf8", maxBuffer: 10 * 1024 * 1024 },
);

const stylesheet = readFileSync(join(directory, "style.css"), "utf8");
const template = readFileSync(join(directory, "index.html"), "utf8");
const stylesheetTag = '<link rel="stylesheet" href="style.css" />';
const scriptTag = '<script type="module" src="app.mjs"></script>';

// 템플릿이 바뀌어 교체에 실패하면 불완전한 실행 파일을 저장하지 않고 멈춥니다.
if (!template.includes(stylesheetTag) || !template.includes(scriptTag)) {
  throw new Error(
    "index.html의 CSS·스크립트 참조가 바뀌었습니다. 빌드 처리의 교체 대상을 확인하세요.",
  );
}

// 문자열 속 닫기 태그가 HTML의 실제 script 끝으로 해석되지 않도록 보호합니다.
const embeddedScript = javascript.replace(/<\/script/gi, "<\\/script");
let html = template
  .replace(stylesheetTag, () => `<style>\n${stylesheet}\n</style>`)
  .replace(scriptTag, () => `<script>\n${embeddedScript}\n</script>`)
  // 파일을 다른 이름으로 저장해도 로고 클릭이 폴더가 아닌 현재 파일을 다시 열게 합니다.
  .replace('<a class="brand" href="./"', '<a class="brand" href=""');

// 원본 웹사이트는 WebP 파일을 읽고, 다운로드판은 같은 파일을 내장하여 오프라인에서도 표시합니다.
for (const art of Object.values(ACT_ART)) {
  const uri = `data:image/webp;base64,${readFileSync(join(directory, art.src)).toString("base64")}`;
  html = html.replaceAll(art.src, uri);
}
writeFileSync(outputPath, `${generatedMarker}\n${html}`, "utf8");
console.log(`단일 실행 파일 생성: ${outputPath}`);
